#!/bin/bash
#
# Bastion user data, read verbatim by `lib/bastion-stack.ts` at synth time.
#
# Cloud-init runs user data once per *instance*, not once per boot, so this
# installs a systemd oneshot unit and lets that do the per-boot work.
#
# PARAM below is the one name in this repo written out by hand rather than
# generated by `derrops-conventions`. test/bastion-stack.test.ts asserts it
# equals `naming.name({ type: 'ssmParam', key: 'endpoint' })`, so a convention
# change fails the build instead of silently writing the wrong parameter.
#
# It is called "endpoint", not "host", because the value is only incidentally a
# public DNS name: swap the auto-assigned public IPv4 for an Elastic IP later
# and this can publish the address itself without the name going stale.
set -euo pipefail

cat >/usr/local/sbin/derrops-publish-endpoint <<'SCRIPT'
#!/bin/bash
# Publish this instance's current public DNS name to SSM Parameter Store.
# The hostname encodes the auto-assigned (non-Elastic) public IPv4, so it
# changes on every stop/start — hence republishing on each boot.
set -euo pipefail

PARAM='/derrops/region/bastion/endpoint'
IMDS='http://169.254.169.254/latest'

# Region comes from IMDS too, so nothing region-specific is baked into the box.
token=$(curl -sf -X PUT "$IMDS/api/token" \
  -H 'X-aws-ec2-metadata-token-ttl-seconds: 300')
imds() { curl -sf -H "X-aws-ec2-metadata-token: $token" "$IMDS/meta-data/$1"; }

region=$(imds placement/region)
host=$(imds public-hostname || true)

# A just-started instance can briefly have no public IPv4; failing loudly beats
# overwriting a good value with an empty string. systemd retries (see below).
if [ -z "$host" ]; then
  echo "no public hostname assigned yet; leaving $PARAM unchanged" >&2
  exit 1
fi

aws ssm put-parameter --region "$region" \
  --name "$PARAM" --type String --value "$host" --overwrite \
  --description 'Public DNS name of the bastion, republished on each boot.'
echo "published $PARAM=$host"
SCRIPT
chmod 0755 /usr/local/sbin/derrops-publish-endpoint

cat >/etc/systemd/system/derrops-publish-endpoint.service <<'UNIT'
[Unit]
Description=Publish the bastion public DNS name to SSM Parameter Store
After=network-online.target
Wants=network-online.target
StartLimitIntervalSec=300
StartLimitBurst=5

[Service]
Type=oneshot
ExecStart=/usr/local/sbin/derrops-publish-endpoint
Restart=on-failure
RestartSec=10

[Install]
WantedBy=multi-user.target
UNIT

systemctl daemon-reload
systemctl enable --now derrops-publish-endpoint.service
